import{_ as i,o as t,c as u,a2 as n}from"./chunks/framework.CqpfiAoK.js";const e=JSON.parse('{"title":"Watu na Mashirika Muhimu","description":"","frontmatter":{},"headers":[],"relativePath":"sw/95-关键人物与组织.md","filePath":"sw/95-关键人物与组织.md","lastUpdated":1789183869000}'),h={name:"sw/95-关键人物与组织.md"};function d(w,a,k,m,o,l){return t(),u("div",null,[...a[0]||(a[0]=[n('<h1 id="watu-na-mashirika-muhimu" tabindex="-1">Watu na Mashirika Muhimu <a class="header-anchor" href="#watu-na-mashirika-muhimu" aria-label="Permalink to &quot;Watu na Mashirika Muhimu&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya hati</td><td>95</td></tr><tr><td>Moduli</td><td>Viambatanisho na Vifaa vya Rujia</td></tr><tr><td>Maneno muhimu</td><td>watu muhimu, mashirika muhimu, majukumu ya kihistoria, kazi za taasisi, utamaduni wa usawa</td></tr></tbody></table><h2 id="_1-maelezo" tabindex="-1">1. Maelezo <a class="header-anchor" href="#_1-maelezo" aria-label="Permalink to &quot;1. Maelezo&quot;">​</a></h2><p>Hati hii inajumuisha watu muhimu na mashirika muhimu katika safari ya maendeleo ya Ustaarabu wa Usawa wa Nanga, imeandaliwa kulingana na enzi za kihistoria na aina za mashirika. Sehemu ya watu muhimu inaorodhesha jina la mtu, enzi, mchango wa msingi, na nafasi ya kihistoria; sehemu ya mashirika muhimu inaorodhesha jina la shirika, wakati wa kuanzishwa, kazi ya msingi, na jukumu la kihistoria. Hati hii ni hati ya sasisho la harakati; pamoja na maendeleo ya historia na mageuzi ya mashirika, itaendelea kuongezwa na kusahihishwa.</p><h2 id="_2-watu-muhimu" tabindex="-1">2. Watu Muhimu <a class="header-anchor" href="#_2-watu-muhimu" aria-label="Permalink to &quot;2. Watu Muhimu&quot;">​</a></h2><h3 id="_2-1-wataalamu-wa-fikira-katika-enzi-ya-kabla-ya-nanga" tabindex="-1">2.1 Wataalamu wa Fikira katika Enzi ya Kabla ya Nanga <a class="header-anchor" href="#_2-1-wataalamu-wa-fikira-katika-enzi-ya-kabla-ya-nanga" aria-label="Permalink to &quot;2.1 Wataalamu wa Fikira katika Enzi ya Kabla ya Nanga&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jina la mtu</th><th>Enzi</th><th>Mchango wa msingi</th><th>Nafasi ya kihistoria</th></tr></thead><tbody><tr><td>Xuan Hengzi</td><td>Takriban -500 milioni ya miaka</td><td>Mwanafalsafa wa kwanza aliyefikiria kwa mfumo juu ya mfumo wa u cultivating wa kuitoaji, alipendekeza kielelezo cha awali cha dhana ya &quot;usawa&quot;, mwandishi wa kiungo kilichobaki cha &quot;Nadharia ya Kupinga Kuitoaji&quot;</td><td>Mwanzilishi wa kale wa fikira ya usawa, ambayo fikira yake, baada ya mamia ya mabilioni ya miaka ya kulala, ikawa chanzo cha kiroho cha Ustaarabu wa Usawa wa Nanga</td></tr><tr><td>Wan Lingmu</td><td>Takriban -100 milioni ya miaka</td><td>Aliongoza utamaduni wa kwanza wa majaribio ya usawa wa ukubwa mkubwa; ingawa mwishowe uliibiwa na utamaduni wa kuitoaji, mazoezi yake yalithibitisha uwezekano wa mfumo wa usawa</td><td>Mwanzo wa mazoezi ya usawa, anaheshimiwa na vizazi vifuatavyo kama &quot;Mama wa Usawa&quot;</td></tr><tr><td>Mao Juezhe</td><td>Takriban -10,000 miaka</td><td>Mtu anayefanya u cultivating kutoka usawa wa kwanza, kwa bahati anahisi nodi za kudumu katika mtandao wa sherea wakati wa u cultivating wa muda mrefu, anagundua mchakato wa nanga</td><td>Mmgundua wa mchakato wa nanga, mwanzo wa enzi ya uamsho wa nanga</td></tr></tbody></table><h3 id="_2-2-waanzilishi-wa-enzi-ya-uamsho-wa-nanga" tabindex="-1">2.2 Waanzilishi wa Enzi ya Uamsho wa Nanga <a class="header-anchor" href="#_2-2-waanzilishi-wa-enzi-ya-uamsho-wa-nanga" aria-label="Permalink to &quot;2.2 Waanzilishi wa Enzi ya Uamsho wa Nanga&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jina la mtu</th><th>Enzi</th><th>Mchango wa msingi</th><th>Nafasi ya kihistoria</th></tr></thead><tbody><tr><td>Mao Dinggong</td><td>-10000 hadi -9200 miaka</td><td>Mwanafunzi wa Mao Juezhe, alifanya utafiti wa mfumo wa mchakato wa nanga, alijenga nanga ya kwanza ya bandia, mwandishi wa &quot;Kanuni za Nanga&quot;</td><td>Mwanzilishi wa teknolojia ya nanga, mvumbuzi wa nanga ya bandia</td></tr><tr><td>Gong Shengzi</td><td>-6000 hadi -5100 miaka</td><td>Alunganisha teknolojia ya nanga na fikira ya usawa, alianzisha mfumo wa kibunifu wa &quot;Usawa wa Nanga&quot;, mwandishi wa &quot;Nadharia ya Usawa wa Nanga&quot;</td><td>Mwanzilishi wa nadharia ya usawa wa nanga, mwalimu wa kiroho wa utamaduni wa usawa</td></tr><tr><td>Heng Yuangong</td><td>-5000 hadi -4300 miaka</td><td>Alijenga mji-wa-taifa wa kwanza wa aina ya usawa uliojengwa kwa msingi wa nanga, &quot;Mji wa Heng Yuan&quot;, na alizuia kwa mafanikio shambulio la utamaduni wa kuitoaji</td><td>Mwanzilishi wa mji-wa-taifa wa kwanza wa aina ya usawa, mtu anayetekeleza mfumo wa usawa</td></tr><tr><td>Wan Zushi</td><td>-2000 hadi -1200 miaka</td><td>Alianzisha &quot;Mkutano wa Usawa wa Kabila Zote&quot; wa kwanza, akizungumzia makabila kadhaa akishirikisha muungano wa usawa</td><td>Mzunguzi wa muungano wa kabila zote, mwanzilishi wa usawa wa kati ya makabila</td></tr></tbody></table><h3 id="_2-3-waanzilishi-wa-nchi-katika-kipindi-cha-usanifu-wa-mfumo-wa-usawa" tabindex="-1">2.3 Waanzilishi wa Nchi katika Kipindi cha Usanifu wa Mfumo wa Usawa <a class="header-anchor" href="#_2-3-waanzilishi-wa-nchi-katika-kipindi-cha-usanifu-wa-mfumo-wa-usawa" aria-label="Permalink to &quot;2.3 Waanzilishi wa Nchi katika Kipindi cha Usanifu wa Mfumo wa Usawa&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jina la mtu</th><th>Enzi</th><th>Mchango wa msingi</th><th>Nafasi ya kihistoria</th></tr></thead><tbody><tr><td>Li Xiangong</td><td>-1000 hadi -900 miaka</td><td>Mwenyekiti wa Kamati ya Kuandaa Katiba ya Usawa, aliongoza kuandaa &quot;Katiba ya Usawa&quot;, alichocheza kupitishwa kwa katiba kupitia kura ya taifa</td><td>Mwandishi wa msingi wa Katiba ya Usawa, baba wa katiba ya utamaduni wa usawa</td></tr><tr><td>Zhi Fagong</td><td>-9000 hadi -780 miaka</td><td>Mwenyekiti wa kwanza wa Kamati ya Utendaji wa Usawa, aliongoza usanifu wa mfumo wa utendaji wa utamaduni wa usawa na mchakato wa utekelezaji wa sheria</td><td>Mwanzilishi wa mfumo wa utendaji wa usawa, mkuu wa kwanza wa utendaji</td></tr><tr><td>Si Famu</td><td>-9000 hadi -800 miaka</td><td>Mwanajeshi wa kwanza wa Mahakama ya Usawa, alianzisha mfumo wa mahakama wa utamaduni wa usawa na mfumo wa ukaguzi wa asheria</td><td>Mwanzilishi wa mfumo wa mahakama wa usawa, mkuu wa kwanza wa mahakama</td></tr><tr><td>San Baishi</td><td>-500 hadi -300 miaka</td><td>Aliongoza kazi ya kuchimba na kupanga mfumo wa u cultivating wa asili wa mia tatu, akaongoza timu kukamilisha uthibitisho wa mfumo wote wa mia tatu</td><td>Mpangaji wa jumla wa mfumo wa mia tatu, mkurugenzi wa jumla wa mradi wa kufungua u cultivating</td></tr><tr><td>Bei Zenggong</td><td>-300 hadi -220 miaka</td><td>Aliongoza utafiti wa matumizi ya teknolojia ya tunda la mara mbili, alifikia maendeleo ya uhandisi wa teknolojia ya kuongeza makosa ya mara mia moja</td><td>Mwanasayansi wa kwanza wa teknolojia ya tunda la mara mbili, mchochezi wa mfumo wa kurudia makosa</td></tr></tbody></table><h3 id="_2-4-viongozi-katika-kipindi-cha-kufunguliwa-na-uanzishaji" tabindex="-1">2.4 Viongozi katika Kipindi cha Kufunguliwa na Uanzishaji <a class="header-anchor" href="#_2-4-viongozi-katika-kipindi-cha-kufunguliwa-na-uanzishaji" aria-label="Permalink to &quot;2.4 Viongozi katika Kipindi cha Kufunguliwa na Uanzishaji&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jina la mtu</th><th>Enzi</th><th>Mchango wa msingi</th><th>Nafasi ya kihistoria</th></tr></thead><tbody><tr><td>Kai Fanggong</td><td>-100 hadi -50 miaka</td><td>Aliongoza kazi ya kufunguliwa kamili ya mfumo wa u cultivating wa asili wa mia tatu, alianzisha mfumo wa mgawanyo wa rasilimali za u cultivating na mtandao wa walimu</td><td>Mkurugenzi wa jumla wa kufunguliwa kwa mfumo wa mia tatu, mtu anayetekeleza &quot;kila mtu ana njia&quot;</td></tr><tr><td>Ji Huogong</td><td>-50 miaka hadi mwaka wa asili</td><td>Aliongoza utekelezaji wa mkakati wa uanzishaji wa 20%, akaongoza timu kukamilisha lengo la uanzishaji wa 20% ya viumbe vyenye fahamu ndani ya miaka 50</td><td>Mkurugenzi wa jumla wa mkakati wa uanzishaji wa 20%, mwanzo wa enzi mpya ya utamaduni wa usawa</td></tr><tr><td>Sheng Weigong</td><td>Mwaka wa asili hadi 80 miaka</td><td>Aliongoza mradi wa kuongeza kiwango cha kwanza, alichocheza utekelezaji wa njia ya kuongeza kiwango cha hatua nne, alifikia kuongeza kiwango cha hatua ya kwanza</td><td>Mhandisi wa jumla wa kuongeza kiwango cha kwanza, miongozi wa enzi ya kuongeza kiwango</td></tr></tbody></table><h3 id="_2-5-wachunguzi-katika-enzi-ya-jamhuri-ya-kabila-zote-na-kati-ya-usawa" tabindex="-1">2.5 Wachunguzi katika Enzi ya Jamhuri ya Kabila Zote na Kati ya Usawa <a class="header-anchor" href="#_2-5-wachunguzi-katika-enzi-ya-jamhuri-ya-kabila-zote-na-kati-ya-usawa" aria-label="Permalink to &quot;2.5 Wachunguzi katika Enzi ya Jamhuri ya Kabila Zote na Kati ya Usawa&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jina la mtu</th><th>Enzi</th><th>Mchango wa msingi</th><th>Nafasi ya kihistoria</th></tr></thead><tbody><tr><td>Wan Zu Gongzhu</td><td>100 hadi 200 miaka</td><td>Aliongoza kazi ya kuanzishwa wa Jamhuri ya Kabila Zote, alichocheza kuandaa orodha ya kabila zote na sera ya kuunganisha kati ya makabila</td><td>Mwanzilishi wa Jamhuri ya Kabila Zote, mkuu wa kwanza wa Jamhuri ya Kabila Zote</td></tr><tr><td>Wei Mianmu</td><td>500 hadi 650 miaka</td><td>Mkurugenzi wa kwanza wa Ofisi ya Usimamizi wa Usawa, aliongoza mpango wa uchunguzi wa kati ya usawa wa ukubwa mkubwa, alijenga hazina ya jumla ya mawasiliano ya usawa</td><td>Mwanzilishi wa uchunguzi wa kati ya usawa, mwanzilishi wa mfumo wa usimamizi wa usawa</td></tr><tr><td>Kao Gugong</td><td>800 hadi 950 miaka</td><td>Aliongoza ukomavu wa mwisho wa mpango wa kale wa mbali wa kioo cha nakala, alichocheza kale za kati ya usawa kuingia katika enzi ya kiwango</td><td>Mtaalamu wa jumla wa mpango wa kale, mwanzilishi wa kale za kati ya usawa</td></tr><tr><td>Shi Lügong</td><td>1000 hadi 1150 miaka</td><td>Aliongoza maendeleo ya teknolojia ya kurudia nyuma kwa muda, alichocheza usanifu wa kanuni ya &quot;kwanza kuchunguza, kisha kuingilia kwa kikomo&quot;</td><td>Miongozi wa teknolojia ya kurudia nyuma kwa muda, mwanzilishi wa kanuni za sheria za muda</td></tr></tbody></table><h2 id="_3-mashirika-muhimu" tabindex="-1">3. Mashirika Muhimu <a class="header-anchor" href="#_3-mashirika-muhimu" aria-label="Permalink to &quot;3. Mashirika Muhimu&quot;">​</a></h2><h3 id="_3-1-mashirika-ya-nguvu-ya-juu-zaidi" tabindex="-1">3.1 Mashirika ya Nguvu ya Juu zaidi <a class="header-anchor" href="#_3-1-mashirika-ya-nguvu-ya-juu-zaidi" aria-label="Permalink to &quot;3.1 Mashirika ya Nguvu ya Juu zaidi&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jina la shirika</th><th>Wakati wa kuanzishwa</th><th>Kazi ya msingi</th><th>Jukumu la kihistoria</th></tr></thead><tbody><tr><td>Baraza la Nanga</td><td>-900 miaka</td><td>Shirika la nguvu ya juu zaidi ya utamaduni wa usawa, linalojumuisha uwakilishi wa kabila zote kwa uwiano, linaitumikia mamlaka ya kisheria na mamlaka ya kufanya maamuzi juu ya mambo muhimu</td><td>Shirika la juu la kufanya maamuzi la utamaduni wa usawa, mwanzilishi wa sheria zote na mikakati muhimu</td></tr><tr><td>Kamati ya Utendaji wa Usawa</td><td>-900 miaka</td><td>Shirika la juu la utendaji wa utamaduni wa usawa, linalohusika na utekelezaji wa katiba na sheria, utawala wa kila siku</td><td>Shirika la juu la utendaji wa utamaduni wa usawa, mtu anayetekeleza sheria na sera</td></tr><tr><td>Mahakama ya Usawa</td><td>-900 miaka</td><td>Shirika la juu la mahakama wa utamaduni wa usawa, linafanya mamlaka ya hukumu kwa uhuru, linalohusika na ukaguzi wa asheria na kusikiliza kesi muhimu</td><td>Shirika la juu la mahakama wa utamaduni wa usawa, mlinzi wa utawala wa sheria</td></tr><tr><td>Kamati ya Ufuatiliaji wa Nanga</td><td>-900 miaka</td><td>Shirika la ufuatiliaji huru, linalohusika na kufuatilia mashirika yote ya nguvu, kuzuia utumiaji mbaya wa nguvu</td><td>Shirika la ufuatiliaji huru la utamaduni wa usawa, kiungo muhimu katika usawazishaji wa nguvu</td></tr></tbody></table><h3 id="_3-2-mashirika-ya-usimamizi-maalum" tabindex="-1">3.2 Mashirika ya Usimamizi maalum <a class="header-anchor" href="#_3-2-mashirika-ya-usimamizi-maalum" aria-label="Permalink to &quot;3.2 Mashirika ya Usimamizi maalum&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jina la shirika</th><th>Wakati wa kuanzishwa</th><th>Kazi ya msingi</th><th>Jukumu la kihistoria</th></tr></thead><tbody><tr><td>Ofisi ya Usimamizi wa Usawa</td><td>500 miaka</td><td>Inahusika na kudumisha hazina ya jumla ya mawasiliano ya usawa, kupitisha idhini ya safari, kusimamia kale za kati ya usawa, kuratibu ubalozi wa kati ya usawa</td><td>Shirika kuu la mwingiliano wa kati ya usawa, msimamizi wa uchunguzi wa usawa</td></tr><tr><td>Kamati ya Sheria za Muda</td><td>1000 miaka</td><td>Inahusika na kupitisha operesheni za kurudia nyuma kwa muda, utafiti wa sheria za muda, kufuatilia kuzuia paradoksi za muda</td><td>Shirika la kupitisha na kufuatilia operesheni za kurudia nyuma kwa muda, mlinzi wa usalama wa sheria za muda</td></tr><tr><td>Kamati ya Ukaguzi wa Sheria za Muda</td><td>1050 miaka</td><td>Inahusika na ukaguzi wa baada ya operesheni za kurudia nyuma kwa muda, kuthibitisha kwamba haijaleta usumbufu wa mstari wa muda usiozelekwa</td><td>Shirika la ukaguzi huru wa operesheni za muda, mstari wa mwisho wa ulinzi wa usalama wa kurudia nyuma kwa muda</td></tr><tr><td>Kamati ya Maadili ya Kati ya Usawa</td><td>600 miaka</td><td>Inaweka na inafasiri kanuni za maadili ya kati ya usawa, inapitisha miradi ya mwingiliano wa kati ya usawa yenye hatari kubwa, inapokea malalamiko ya ukiukaji wa maadili</td><td>Shirika la ufuatiliaji wa maadili wa mwingiliano wa kati ya usawa, mlinzi wa uwezo wa kujitegemea wa utamaduni</td></tr><tr><td>Ofisi ya Ukaguzi wa Kurudisha Maarifa</td><td>850 miaka</td><td>Inahusika na ukaguzi wa operesheni za kurudisha maarifa, kuhakikisha kwamba maudhui yaliyorudishwa yanafuata kanuni ya &quot;kurudisha maarifa tu&quot;</td><td>Shirika la ukaguzi wa kurudisha maarifa, kiungo muhimu katika kuzuia uchafuzi wa kati ya usawa</td></tr></tbody></table><h3 id="_3-3-mashirika-ya-utafiti-na-elimu" tabindex="-1">3.3 Mashirika ya Utafiti na Elimu <a class="header-anchor" href="#_3-3-mashirika-ya-utafiti-na-elimu" aria-label="Permalink to &quot;3.3 Mashirika ya Utafiti na Elimu&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jina la shirika</th><th>Wakati wa kuanzishwa</th><th>Kazi ya msingi</th><th>Jukumu la kihistoria</th></tr></thead><tbody><tr><td>Taasisi ya Utafiti wa Nanga</td><td>-8000 miaka</td><td>Utafiti wa msingi wa mchakato wa nanga na ukuzaji wa matumizi, ujenzi na kudumisha nanga za bandia</td><td>Shirika kuu la utafiti wa teknolojia ya nanga, mojawapo ya vyanzo vya teknolojia ya utamaduni wa usawa</td></tr><tr><td>Kamati ya Kupanga Mfumo wa Mia Tatu</td><td>-500 miaka</td><td>Kuchimba, kupanga, kuthibitisha na kuboresha kwa kuzungumzia mfumo wa u cultivating wa asili wa mia tatu</td><td>Shirika la kupanga na kudumisha mfumo wa mia tatu, msaada wa teknolojia wa kufungua u cultivating</td></tr><tr><td>Shirikisho la Vyuo vya Usawa</td><td>-700 miaka</td><td>Shirika la muungano wa elimu ya juu na elimu ya u cultivating, linalohusika na mafunzo ya vipaa vya juu na utafiti wa kitaaluma</td><td>Shirikisho la vyuo vya juu vya utamaduni wa usawa, kiini cha mafunzo ya vipaavu na ubunifu wa kitaaluma</td></tr><tr><td>Chuo cha Kale cha Kati ya Usawa</td><td>550 miaka</td><td>Inafunza vipaavu vya kitaaluma vya kale za kati ya usawa, inafanya utafiti wa teknolojia ya kale na ubunifu wa mbinu</td><td>Kituo cha mafunzo ya vipaavu na utafiti wa teknolojia wa kale za kati ya usawa</td></tr><tr><td>Taasisi ya Utafiti wa Sheria za Muda</td><td>950 miaka</td><td>Utafiti wa msingi wa kibunifu wa sheria za muda na utafiti na ukuzaji wa teknolojia ya kurudia nyuma kwa muda</td><td>Shirika kuu la utafiti wa sheria za muda, mahali pa kuzalisha teknolojia ya kurudia nyuma kwa muda</td></tr></tbody></table><h3 id="_3-4-mashirika-ya-kijeshi-na-usalama" tabindex="-1">3.4 Mashirika ya Kijeshi na Usalama <a class="header-anchor" href="#_3-4-mashirika-ya-kijeshi-na-usalama" aria-label="Permalink to &quot;3.4 Mashirika ya Kijeshi na Usalama&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jina la shirika</th><th>Wakati wa kuanzishwa</th><th>Kazi ya msingi</th><th>Jukumu la kihistoria</th></tr></thead><tbody><tr><td>Jeshi la Ulinzi wa Usawa</td><td>-850 miaka</td><td>Nguvu ya ulinzi ya kawaida ya utamaduni wa usawa, inahusika na ulinzi wa usawa na kushirikiana na vitisho vya nje</td><td>Nguvu kuu ya kijeshi ya utamaduni wa usawa, mlinzi wa usalama wa taifa</td></tr><tr><td>Timu ya Doria la Usawa</td><td>520 miaka</td><td>Inahusika na doria na ufuatiliaji wa usalama wa usawa uliochunguziwa, inashirikiana na matukio ya usalama ya kati ya usawa</td><td>Nguvu ya mstari wa mbele wa usalama wa kati ya usawa, mlinzi wa utaratibu wa usawa</td></tr><tr><td>Timu ya Dharura ya Uchafuzi wa Sheria</td><td>600 miaka</td><td>Inahusika na mwitikio wa dharura na kuondoa uchafuzi katika matukio ya uchafuzi wa sheria na uchafuzi wa nishati</td><td>Nguvu ya mwitikio wa dharura ya uchafuzi wa sheria, mlinzi wa mazingira ya ulimwengu</td></tr><tr><td>Kikundi cha Dharura cha Paradoksi ya Muda</td><td>1020 miaka</td><td>Inahusika na mwitikio wa dharura na operesheni za urekebishaji wa sababu katika matukio ya paradoksi ya muda</td><td>Nguvu ya mwitikio wa dharura ya paradoksi ya muda, dhamana ya mwisho ya utulivu wa mstari wa muda</td></tr></tbody></table><h3 id="_3-5-mashirika-ya-raia-na-jamii" tabindex="-1">3.5 Mashirika ya Raia na Jamii <a class="header-anchor" href="#_3-5-mashirika-ya-raia-na-jamii" aria-label="Permalink to &quot;3.5 Mashirika ya Raia na Jamii&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jina la shirika</th><th>Wakati wa kuanzishwa</th><th>Kazi ya msingi</th><th>Jukumu la kihistoria</th></tr></thead><tbody><tr><td>Mkutano wa Usawa wa Kabila Zote</td><td>-2000 miaka</td><td>Mkutano wa mara kwa mara wa uwakilishi wa kabila zote, kujadili mambo ya usawa wa kati ya makabila, kukuza ubadilishaji wa kitamaduni</td><td>Jukwaa muhimu kwa ubadilishaji wa kabila zote, shirika la mwanzo wa Jamhuri ya Kabila Zote</td></tr><tr><td>Chama cha Watu wanaofanya U cultivating</td><td>-600 miaka</td><td>Shirika la utawala wa kitaaluma cha watu wanaofanya u cultivating, linalohusika na kulinda haki za watu wanaofanya u cultivating, kuweka viwango vya kitaaluma</td><td>Shirika la utawala wa watu wanaofanya u cultivating, mchochezi wa kiwango cha tasnia ya u cultivating</td></tr><tr><td>Chama cha Watumiaji</td><td>-650 miaka</td><td>Shirika la kulinda haki za watumiaji, linalohusika na kulinda haki za watumiaji, elimu ya watumiaji, ufuatiliaji wa jamii</td><td>Mwendesha wa haki za watumiaji, mfuatiliaji wa jamii wa utaratibu wa soko</td></tr><tr><td>Shirikisho la Ulinzi wa Mazingira</td><td>-550 miaka</td><td>Shirika la muungano wa raia wa ulinzi wa mazingira, linalohusika na ufuatiliaji wa mazingira, elimu ya mazingira, shughuli za kujitolea za urejeshaji wa mazingira</td><td>Nguvu ya jamii ya ulinzi wa mazingira, mchochezi wa utamaduni wa mazingira ya ulimwengu</td></tr><tr><td>Chama cha Urafiki wa Kati ya Usawa</td><td>580 miaka</td><td>Shirika la raia linalokuza ubadilishaji wa urafiki kati ya utamaduni wa kati ya usawa, linalohusika na ubalozi wa raia, ubadilishaji wa kitamaduni</td><td>Nguvu kuu ya ubalozi wa raia wa kati ya usawa, daraja la uelewa kati ya utamaduni</td></tr></tbody></table><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Watu na mashirika muhimu ni wabebaji hai wa historia ya Ustaarabu wa Usawa wa Nanga. Kutoka kwa wataalamu wa fikira wa kale hadi kwa viongozi wa utamaduni wa kisasa, kutoka kwa mashirika ya nguvu ya juu zaidi hadi kwa mashirika ya jamii ya raia, kila mtu na shirika anacheza jukumu lisiloweza kubadilishwa katika hadithi kubwa ya utamaduni wa usawa. Pambano lao na michango yao pamoja zimeunda epik ya kushangaza ya Ustaarabu wa Usawa wa Nanga, kutoka kwa kutokuwa hadi kuwepo, kutoka kwa mdogo hadi mkubwa, kutoka kwa usawa wa mwenyewe hadi ulimwengu wote.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>50-Jedwali la Jumla la Mgawanyo wa Enzi</li><li>49-Mfumo wa Utawala na Usawazishaji wa Nguvu</li><li>77-Uanzishaji wa Jamhuri ya Kabila Zote</li></ul>',30)])])}const r=i(h,[["render",d]]);export{e as __pageData,r as default};
